TASK(CAN_Task)
{
#ifdef USB_LOGGING
	printf("Task CAN_Task running...\r\n");
#endif

	static uint32_t counter = 0;
	static CAN_RxHeaderTypeDef rxHeader;
	static uint8_t rxData[8];

	uint8_t CanMsg_1[8] = {0, 0, 0, 0, 0, 0, 0xAA, 0xBB};
	uint8_t CanMsg_2[8] = {0, 0, 0, 0, 0, 0, 0, 0};

	/* Can msg 1 */
	counter++;
	CanMsg_1[0] = counter >> 24;
	CanMsg_1[1] = counter >> 16;
	CanMsg_1[2] = counter >> 8;
	CanMsg_1[3] = counter;

	CanMsg_2[0] = adc_in1 >> 8;
	CanMsg_2[1] = adc_in1;
	CanMsg_2[2] = adc_in2 >> 8;
	CanMsg_2[3] = adc_in2;

	CAN_SendMessage(0x123, 8, CanMsg_1);
	CAN_SendMessage(0x456, 8, CanMsg_2);

	/* CAN Rx */
	if (HAL_CAN_GetRxFifoFillLevel(&hcan, CAN_RX_FIFO0) > 0)
	{
	    if (HAL_CAN_GetRxMessage(&hcan, CAN_RX_FIFO0, &rxHeader, rxData) == HAL_OK)
	    {
	        // rxHeader.StdId  -> ID (se standard)
	        // rxHeader.ExtId  -> ID (se extended)
	        // rxHeader.DLC    -> numero byte validi
	        // rxData[]        -> payload
	    	if (rxHeader.StdId == 0x100)
	    	{
	    		if ((rxData[0] == 0) || (rxData[0] == 1))
	    			HAL_GPIO_WritePin(LED_1_GPIO_Port, LED_1_Pin, rxData[0]);
	    		else
	    			HAL_GPIO_TogglePin(LED_1_GPIO_Port, LED_1_Pin);
		    	HAL_GPIO_WritePin(LED_2_GPIO_Port, LED_2_Pin, rxData[1]);
		    	HAL_GPIO_WritePin(LED_3_GPIO_Port, LED_3_Pin, rxData[2]);
		    	if ((rxData[3] == 0) || (rxData[3] == 1))
		    		HAL_GPIO_WritePin(BUZZ_GPIO_Port, BUZZ_Pin, rxData[3]);
	    		else
	    			HAL_GPIO_TogglePin(BUZZ_GPIO_Port, BUZZ_Pin);
	    	}
	    }
	}


	/* Task Termination */
	Os_TerminateTask();
}

