TASK(Readings_Task)
{
#ifdef USB_LOGGING
	printf("Task Readings_Task running...\r\n");
#endif

	ADC_ChannelConfTypeDef sConfig = {0};

	/* IN1 */
	sConfig.Channel = ADC_CHANNEL_1;          // IN1 = PA1
	sConfig.Rank = ADC_REGULAR_RANK_1;
	sConfig.SamplingTime = ADC_SAMPLETIME_28CYCLES_5;
	HAL_ADC_ConfigChannel(&hadc1, &sConfig);

	HAL_ADC_Start(&hadc1);
	HAL_ADC_PollForConversion(&hadc1, HAL_MAX_DELAY);
	adc_in1 = HAL_ADC_GetValue(&hadc1);
	HAL_ADC_Stop(&hadc1);

	/* IN2 */
	sConfig.Channel = ADC_CHANNEL_2;          // IN2 = PA2
	sConfig.Rank = ADC_REGULAR_RANK_1;        // sempre rank 1 perché scan è OFF
	HAL_ADC_ConfigChannel(&hadc1, &sConfig);

	HAL_ADC_Start(&hadc1);
	HAL_ADC_PollForConversion(&hadc1, HAL_MAX_DELAY);
	adc_in2 = HAL_ADC_GetValue(&hadc1);
	HAL_ADC_Stop(&hadc1);

	/* Conversione ADC → tensione */
	voltage = ((float)adc_in2 * 3.3f) / 4095.0f;

	/* LM35: 10 mV per °C */
	temperature_c = (voltage * 100.0f) + 10;

	/* Task Termination */
	Os_TerminateTask();
}

